#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> K(n);
    vector<vector<pair<int,int>>> cells(n);
    int totalCells = 0;
    for(int i=0;i<n;i++){
        cin >> K[i];
        cells[i].resize(K[i]);
        for(int j=0;j<K[i];j++) cin >> cells[i][j].first >> cells[i][j].second;
        totalCells += K[i];
    }

    // Transform: first flip (f=1 means x -> -x), then rotate r times 90° CCW
    // CCW rotation: (x,y) -> (-y, x)
    auto transform = [](vector<pair<int,int>>& src, int r, int f, vector<pair<int,int>>& dst){
        dst.resize(src.size());
        for(int i=0;i<(int)src.size();i++){
            int x = src[i].first, y = src[i].second;
            if(f) x = -x;
            for(int q=0;q<r;q++){ int t=x; x=-y; y=t; }
            dst[i] = {x,y};
        }
        int mx=INT_MAX, my=INT_MAX;
        for(auto&[x,y]:dst){ mx=min(mx,x); my=min(my,y); }
        for(auto&[x,y]:dst){ x-=mx; y-=my; }
    };

    // Sort pieces largest first
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){ return K[a]>K[b]; });

    int W = max(10, (int)ceil(sqrt(totalCells * 1.2)));

    vector<int> heightmap(W, 0);
    vector<int> ox(n), oy(n), orr(n), of(n);

    vector<pair<int,int>> tc;
    for(int idx=0;idx<n;idx++){
        int pi = order[idx];
        int bestScore = INT_MAX, bx=-1, by=-1, br=0, bf=0;

        for(int f=0;f<2;f++){
            for(int r=0;r<4;r++){
                transform(cells[pi], r, f, tc);
                int tw=0, th=0;
                for(auto&[x,y]:tc){ tw=max(tw,x+1); th=max(th,y+1); }
                if(tw > W) continue;

                for(int x=0; x<=W-tw; x++){
                    int minY=0;
                    for(auto&[cx,cy]:tc){
                        minY = max(minY, heightmap[x+cx] - cy);
                    }
                    int topY=0;
                    for(auto&[cx,cy]:tc) topY=max(topY, minY+cy+1);
                    int score = topY;
                    if(score < bestScore){
                        bestScore = score;
                        bx=x; by=minY; br=r; bf=f;
                    }
                }
            }
        }

        if(bx==-1){ // fallback: extend W
            bx=0; by=heightmap[0]; br=0; bf=0;
        }

        transform(cells[pi], br, bf, tc);
        for(auto&[cx,cy]:tc){
            heightmap[bx+cx] = max(heightmap[bx+cx], by+cy+1);
        }
        ox[pi]=bx; oy[pi]=by; orr[pi]=br; of[pi]=bf;
    }

    int H=0;
    for(int i=0;i<W;i++) H=max(H, heightmap[i]);

    cout << W << " " << H << "\n";
    for(int i=0;i<n;i++){
        cout << ox[i] << " " << oy[i] << " " << orr[i] << " " << of[i] << "\n";
    }

    return 0;
}
